"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["449"],{2773(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/coco-framework/en/overview","label":"Overview","docId":"overview","unlisted":false},{"type":"link","href":"/coco-framework/en/getting-started","label":"Getting Started","docId":"getting-started","unlisted":false},{"type":"link","href":"/coco-framework/en/feature-toggles","label":"Feature Toggles","docId":"feature-toggles","unlisted":false},{"type":"category","label":"Core Web","items":[{"type":"link","href":"/coco-framework/en/features/web-runtime","label":"Web Runtime","docId":"features/web-runtime","unlisted":false},{"type":"link","href":"/coco-framework/en/features/request-security","label":"Request Security (Encryption / Signing / Replay Protection)","docId":"features/request-security","unlisted":false},{"type":"link","href":"/coco-framework/en/features/security-context","label":"Security Context and Security Response Headers","docId":"features/security-context","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Data Access","items":[{"type":"link","href":"/coco-framework/en/features/mybatis-plus","label":"MyBatis-Plus Integration","docId":"features/mybatis-plus","unlisted":false},{"type":"link","href":"/coco-framework/en/features/pagination","label":"Pagination and Sorting","docId":"features/pagination","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Multi-tenancy & Permissions","items":[{"type":"link","href":"/coco-framework/en/features/tenant","label":"Multi-tenancy Isolation","docId":"features/tenant","unlisted":false},{"type":"link","href":"/coco-framework/en/features/data-permission","label":"Data Permission","docId":"features/data-permission","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Rate Limiting & Reliability","items":[{"type":"link","href":"/coco-framework/en/features/rate-limit","label":"Rate Limiting","docId":"features/rate-limit","unlisted":false},{"type":"link","href":"/coco-framework/en/features/idempotency","label":"Idempotency","docId":"features/idempotency","unlisted":false},{"type":"link","href":"/coco-framework/en/features/lock","label":"Distributed Lock","docId":"features/lock","unlisted":false},{"type":"link","href":"/coco-framework/en/features/scheduling","label":"Dynamic Scheduled Tasks","docId":"features/scheduling","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Platform Capabilities","items":[{"type":"link","href":"/coco-framework/en/features/storage","label":"Object Storage","docId":"features/storage","unlisted":false},{"type":"link","href":"/coco-framework/en/features/messaging","label":"Messaging and Events","docId":"features/messaging","unlisted":false},{"type":"link","href":"/coco-framework/en/features/cache","label":"Cache","docId":"features/cache","unlisted":false},{"type":"link","href":"/coco-framework/en/features/notification","label":"Notification","docId":"features/notification","unlisted":false},{"type":"link","href":"/coco-framework/en/features/captcha","label":"Captcha","docId":"features/captcha","unlisted":false},{"type":"link","href":"/coco-framework/en/features/audit","label":"Audit Pipeline","docId":"features/audit","unlisted":false},{"type":"link","href":"/coco-framework/en/features/openapi","label":"OpenAPI Metadata","docId":"features/openapi","unlisted":false},{"type":"link","href":"/coco-framework/en/features/codegen","label":"Code Generation","docId":"features/codegen","unlisted":false},{"type":"link","href":"/coco-framework/en/features/infra","label":"Infrastructure Conventions","docId":"features/infra","unlisted":false}],"collapsed":true,"collapsible":true}],"skillsSidebar":[{"type":"link","href":"/coco-framework/en/skills","label":"Skills Overview","docId":"skills/overview","unlisted":false},{"type":"link","href":"/coco-framework/en/skills/install","label":"Quick Install","docId":"skills/install","unlisted":false},{"type":"link","href":"/coco-framework/en/skills/usage","label":"Usage Guide","docId":"skills/usage","unlisted":false}]},"docs":{"feature-toggles":{"id":"feature-toggles","title":"Feature Toggles","description":"All of Coco\'s built-in capabilities are managed through stable CocoFeature identifiers and can be started and stopped declaratively on the application side. For feature selection, prefer YAML or @CocoFeatures; the older CocoConfigurer Java hook is kept only for compatibility and is no longer recommended.","sidebar":"docsSidebar"},"features/audit":{"id":"features/audit","title":"Audit Pipeline","description":"The Coco audit pipeline (coco-feature-audit) converges the \\"audit-worthy actions\\" produced by the framework and the business into structured audit events, then distributes them to one or more sinks through a unified publisher. Event sources depend only on the publisher and are unaware of the specific sinks, so modules such as Web, Security, and Tenant stay decoupled from the final storage implementation. The module binds the coco.audit namespace, is enabled by default, and participates in auto-configuration as a Coco Feature (CocoFeature.AUDIT).","sidebar":"docsSidebar"},"features/cache":{"id":"features/cache","title":"Cache","description":"Coco cache (coco-cache) provides two-tier caching: L1 is in-process Caffeine, L2 is shared Redis, and writes/evictions are broadcast over Redis pub/sub so every instance\'s L1 stays consistent. It implements Spring\'s CacheManager/Cache, so @Cacheable, @CacheEvict, and friends work out of the box.","sidebar":"docsSidebar"},"features/captcha":{"id":"features/captcha","title":"Captcha","description":"Coco captcha (coco-captcha) provides a type-agnostic generate/verify SPI: image (IMAGE), slider (SLIDER), and SMS code (SMS_CODE). The framework ships local reference implementations (JDK-native AWT image rendering, a numeric slider, a numeric SMS code) plus an in-process answer store; production can register custom generators or a shared store. Off by default \u2014 enable with coco.captcha.enabled=true.","sidebar":"docsSidebar"},"features/codegen":{"id":"features/codegen","title":"Code Generation","description":"Coco code generation (coco-feature-codegen) is a template-based CRUD scaffolding capability. It takes the description of \\"a business resource\\" (package name, resource name, data table, fields) and renders it into maintainable, plain source code through FreeMarker templates, without registering any runtime dynamic CRUD behavior. It is a development-time capability, and the generated output consists of source files owned by the business project itself. The module binds the coco.codegen namespace, is enabled by default, participates in auto-configuration as a Coco Feature (CocoFeature.CODEGEN), and loads after the MyBatis-Plus auto-configuration (the repository and Mapper generated by the built-in CRUD templates depend on MyBatis-Plus).","sidebar":"docsSidebar"},"features/data-permission":{"id":"features/data-permission","title":"Data Permission","description":"Feature Overview","sidebar":"docsSidebar"},"features/idempotency":{"id":"features/idempotency","title":"Idempotency","description":"Coco request idempotency (coco-idempotency) provides write operations with the guarantee that \\"the same request key is successfully processed only once.\\" The client carries an Idempotency-Key in the request header, and at the MVC interceptor layer the framework acquires a lease for each key: the first request obtains the lease and is allowed through, and after successful processing the key is retained until its TTL expires, after which requests carrying the same key return HTTP 409.","sidebar":"docsSidebar"},"features/infra":{"id":"features/infra","title":"Infrastructure Conventions","description":"On top of Spring Boot, Coco consolidates a set of infrastructure conventions that \\"should just be configured this way by default\\": Jackson serialization behavior, async thread pools and context propagation, internationalized messages, and the logging mechanism. They are spread across modules such as coco-spring-boot-autoconfigure, coco-i18n, and coco-logging, and are configured through their respective coco.* namespaces. The goal is to give business projects safe, consistent default behavior out of the box.","sidebar":"docsSidebar"},"features/lock":{"id":"features/lock","title":"Distributed Lock","description":"Coco distributed lock (coco-lock) declares mutually exclusive execution for synchronous business methods via the @CocoLock annotation. It wraps \\"acquire lock \u2192 execute method \u2192 release lock\\" into an AOP aspect: it acquires a lease by lock key before entering the method, releases it in finally after the method returns or throws, and meanwhile a background watchdog automatically renews the lease during method execution, preventing a long-running task from being preempted by others because its lease expires.","sidebar":"docsSidebar"},"features/messaging":{"id":"features/messaging","title":"Messaging and Events","description":"Coco messaging (coco-messaging) provides an in-process publish/subscribe boundary: publish with CocoMessagePublisher, subscribe by declaring @CocoMessageListener, and let configuration decide delivery mode, failure handling, and shutdown behaviour.","sidebar":"docsSidebar"},"features/mybatis-plus":{"id":"features/mybatis-plus","title":"MyBatis-Plus Integration","description":"Overview","sidebar":"docsSidebar"},"features/notification":{"id":"features/notification","title":"Notification","description":"Coco notification (coco-notification) provides a channel-agnostic sending SPI: SMS, email, and in-app. The framework ships only local reference implementations (a logging channel, an in-memory in-app inbox); integrating Aliyun/Tencent SMS, SMTP email, and so on is done by the application bringing its own SDK, implementing CocoNotificationChannel, and registering it as a bean \u2014 the same pure-SPI strategy as object storage, so the framework binds no cloud-vendor dependency.","sidebar":"docsSidebar"},"features/openapi":{"id":"features/openapi","title":"OpenAPI Metadata","description":"Coco OpenAPI metadata (coco-feature-openapi) provides a framework-level, rendering-library-agnostic contract for the basic information of API documentation, and automatically writes this metadata into SpringDoc\'s OpenAPI.info when a business project introduces SpringDoc. It is responsible only for the \\"documentation basic information\\" layer; it does not generate an endpoint inventory and does not take over route scanning. The module binds the coco.openapi namespace, is enabled by default, participates in auto-configuration as a Coco Feature (CocoFeature.OPENAPI), and loads after the Web and Security auto-configurations.","sidebar":"docsSidebar"},"features/pagination":{"id":"features/pagination","title":"Pagination and Sorting","description":"Overview","sidebar":"docsSidebar"},"features/rate-limit":{"id":"features/rate-limit","title":"Rate Limiting","description":"Coco rate limiting (coco-rate-limit) applies request quota control at the Servlet entry point to explicitly declared routes. Each route picks one of three algorithms \u2014 fixed-window, sliding-window, or token-bucket \u2014 all sharing the same \\"limit requests per windowSeconds\\" model. Fixed-window is the default and the simplest; see Choosing an algorithm for when to use the others.","sidebar":"docsSidebar"},"features/request-security":{"id":"features/request-security","title":"Request Security (Encryption / Signing / Replay Protection)","description":"Before a request reaches business code, Coco Web provides three independently toggleable request security filters: AES-GCM request decryption, HMAC-SHA256 signature verification, and replay protection. All three are bound to the coco.web namespace and rely on the request body caching introduced in the previous chapter to re-read the original request body.","sidebar":"docsSidebar"},"features/scheduling":{"id":"features/scheduling","title":"Dynamic Scheduled Tasks","description":"Coco Scheduling (coco-scheduling) provides two capabilities on top of Spring\'s TaskScheduler: declaring method-level scheduled tasks with @CocoScheduled, and programmatically registering, replacing, and cancelling tasks at runtime via CocoTaskScheduler. Compared with the native @Scheduled, it additionally provides stable task names, overlapping-execution policies, execution-result observation, and unified shutdown lifecycle management.","sidebar":"docsSidebar"},"features/security-context":{"id":"features/security-context","title":"Security Context and Security Response Headers","description":"This chapter covers two related but independent capabilities: first, the security context bridging provided by the security feature module (coco-feature-security), which bridges principal information written by a trusted upstream into the current thread; and second, the security response headers and CORS cross-origin configuration provided by the Web module (coco-feature-web).","sidebar":"docsSidebar"},"features/storage":{"id":"features/storage","title":"Object Storage","description":"Coco Object Storage (coco-storage) provides an implementation-agnostic object read/write SPI, along with a ready-to-use, secure streaming local reference implementation. It is responsible only for object content and its stable metadata; it does not provide an HTTP Controller, authorization, an attachment metadata table, or an object key naming strategy \u2014 those are left for the business application to decide. The module is bound to the coco.storage namespace and is disabled by default: the auto-configuration is only created when coco.storage.enabled=true.","sidebar":"docsSidebar"},"features/tenant":{"id":"features/tenant","title":"Multi-tenancy Isolation","description":"Overview","sidebar":"docsSidebar"},"features/web-runtime":{"id":"features/web-runtime","title":"Web Runtime","description":"The Coco Web Runtime (coco-feature-web) consolidates the response structure, exception handling, tracing, and request-body reading that would otherwise be scattered across controllers into a stable, configurable set of infrastructure. It is bound to the coco.web namespace, and its capabilities are decoupled from one another: trace metadata does not pollute the business response structure, and exception responses follow the same response-body rules as normal responses.","sidebar":"docsSidebar"},"getting-started":{"id":"getting-started","title":"Getting Started","description":"This page walks you through integrating Coco Framework into a Spring Boot application in 5 minutes.","sidebar":"docsSidebar"},"overview":{"id":"overview","title":"Overview","description":"A convention-heavy rapid development framework for Spring Boot web services, built for shipping production-ready Java services.","sidebar":"docsSidebar"},"skills/install":{"id":"skills/install","title":"Quick Install","description":"One command writes the MCP config and skill files for your AI agent.","sidebar":"skillsSidebar"},"skills/overview":{"id":"skills/overview","title":"Skills Overview","description":"Teach AI coding assistants to use Coco Framework directly.","sidebar":"skillsSidebar"},"skills/usage":{"id":"skills/usage","title":"Usage Guide","description":"The skills provide 7 MCP tools (called by the agent at runtime) and a set of CLI commands (for humans and CI).","sidebar":"skillsSidebar"}}}}')}}]);